sys_script_fix.script:
var pluginManager = new GlidePluginManager();

if(pluginManager.isActive('com.sn_hr_agent_ws') || pluginManager.isActive('com.sn_hr_wfo')){
	gs.info("AIS Fix script: HR agent WS/WFO is installed. Activating indexed sources");
	var gr = new GlideRecord("ais_datasource");
	gr.addQuery("sys_scope","d4ac3fff5b311200a4656ede91f91af2"); // Scope is Human Resources: Core
	gr.query();

	while(gr.next()){
		gr.active = true;
		gr.update();
	}

}
